#include <DHT.h>


#define DHTPIN 4#define DHTTYPE DHT22 
DHT dht(DHTPIN, DHTTYPE);
#include <BH1750.h>
BH1750 luxMeter;

void setup() {
  Serial.begin(115200);
  dht.begin();
  luxMeter.begin();
  Serial.println("Wokwi D2 Started");
}

void loop() {
  // Lectura DHT22
  float h = dht.readHumidity();
  float t = dht.readTemperature();
  if (isnan(h) || isnan(t)) { Serial.println("Failed to read from DHT!"); } else { 
    Serial.print("Temp: "); Serial.print(t); 
    Serial.print(" "); Serial.print("Hum: "); Serial.println(h); 
  }
  // Lectura BH1750
  luxLevel = luxMeter.readLightLevel();
  Serial.print("Lux: "); Serial.println(luxLevel);
  // Publicar via MQTT
  publishSensorData(t, h, luxLevel);
  delay(30000); 
  // 30 segundos interval
}

void publishSensorData(float temp, float hum, float lux) {
  char payload[128];
  snprintf(payload, sizeof(payload), "{\"temperature\":\"%0.1f\",\"humidity\":\"%0.1f\",\"lux\":\"%0.1f\"}", temp, hum, lux);
  // MQTT publish to campus/ems/D2
  // client.publish("campus/ems/D2", payload);
  Serial.print("Published: "); Serial.println(payload);
}
